//! Compartment search-param FHIRPath expression tables for each FHIR version.
//!
//! For each `(compartment, resource_type)` pair from a FHIR
//! `CompartmentDefinition`, exposes the `(search-param-name,
//! FHIRPath-expression)` pairs that link the resource to the
//! compartment. Used by `helios_sof::compartment` to drive `$viewdefinition-run`'s
//! patient/group filter against raw resource JSON without any runtime
//! data-file dependency — the tables are compiled in.
//!
//! Submodules are generated by `cargo run -p helios-fhir-gen --bin
//! compartment-expressions`; do not edit by hand.

#[cfg(feature = "R4")]
pub mod r4;
#[cfg(feature = "R4B")]
pub mod r4b;
#[cfg(feature = "R5")]
pub mod r5;
#[cfg(feature = "R6")]
pub mod r6;
